CREATE OR REPLACE FUNCTION public.persist_conversation_analysis(p_contact_id uuid, p_analysis jsonb, p_analyzed_at timestamp with time zone, p_expected_projection_updated_at timestamp with time zone, p_should_project boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$ declare v_analysis_id uuid; v_sentiment text := nullif(btrim(coalesce(p_analysis ->> 'sentiment', '')), ''); v_priority text := nullif(btrim(coalesce(p_analysis ->> 'ai_priority', '')), ''); v_projected boolean := false; v_current_projection timestamptz; begin if p_contact_id is null then raise exception 'p_contact_id é obrigatório' using errcode = '22023'; end if; if p_should_project is null then raise exception 'p_should_project é obrigatório' using errcode = '22023'; end if; if not public.ai_is_canonical_sentiment(v_sentiment) then raise exception 'sentiment fora do vocabulário canônico: %', v_sentiment using errcode = '22023'; end if; if not public.ai_is_canonical_priority(v_priority) then raise exception 'ai_priority fora do vocabulário canônico: %', v_priority using errcode = '22023'; end if; if p_should_project then select c.ai_projection_updated_at into v_current_projection from public.contacts c where c.id = p_contact_id for update; if not found then return jsonb_build_object('analysis_id', null, 'projected', false, 'analyzed_at', p_analyzed_at, 'superseded', true, 'current_version', null); end if; if v_current_projection is distinct from p_expected_projection_updated_at then return jsonb_build_object('analysis_id', null, 'projected', false, 'analyzed_at', p_analyzed_at, 'superseded', true, 'current_version', v_current_projection); end if; end if; insert into public.conversation_analyses (contact_id, analyzed_by, summary, sentiment, sentiment_score, customer_satisfaction, key_points, next_steps, topics, urgency, status, message_count, department, relationship_type, agent_performance, churn_risk, sales_opportunity, analysis_version, period_days, coverage, model, analyzed_at) values (p_contact_id, nullif(btrim(coalesce(p_analysis ->> 'analyzed_by', '')), '')::uuid, coalesce(nullif(btrim(coalesce(p_analysis ->> 'summary', '')), ''), 'Análise sem resumo'), v_sentiment, nullif(btrim(coalesce(p_analysis ->> 'sentiment_score', '')), '')::integer, nullif(btrim(coalesce(p_analysis ->> 'customer_satisfaction', '')), '')::integer, public.ai_text_array(p_analysis -> 'key_points'), public.ai_text_array(p_analysis -> 'next_steps'), public.ai_text_array(p_analysis -> 'topics'), nullif(btrim(coalesce(p_analysis ->> 'urgency', '')), ''), coalesce(nullif(btrim(coalesce(p_analysis ->> 'status', '')), ''), 'pendente'), nullif(btrim(coalesce(p_analysis ->> 'message_count', '')), '')::integer, nullif(btrim(coalesce(p_analysis ->> 'department', '')), ''), nullif(btrim(coalesce(p_analysis ->> 'relationship_type', '')), ''), case when jsonb_typeof(p_analysis -> 'agent_performance') = 'object' then p_analysis -> 'agent_performance' else null end, nullif(btrim(coalesce(p_analysis ->> 'churn_risk', '')), ''), nullif(btrim(coalesce(p_analysis ->> 'sales_opportunity', '')), ''), coalesce(nullif(btrim(coalesce(p_analysis ->> 'analysis_version', '')), '')::integer, 2), nullif(btrim(coalesce(p_analysis ->> 'period_days', '')), '')::integer, case when jsonb_typeof(p_analysis -> 'coverage') = 'object' then p_analysis -> 'coverage' else null end, nullif(btrim(coalesce(p_analysis ->> 'model', '')), ''), p_analyzed_at) returning id into v_analysis_id; if p_should_project and (v_sentiment is not null or v_priority is not null) then update public.contacts c set ai_sentiment = coalesce(v_sentiment, c.ai_sentiment), ai_priority = coalesce(v_priority, c.ai_priority), ai_projection_updated_at = greatest(p_analyzed_at, v_current_projection + interval '1 microsecond'), ai_projection_analysis_id = v_analysis_id, updated_at = now() where c.id = p_contact_id; v_projected := found; end if; return jsonb_build_object('analysis_id', v_analysis_id, 'projected', v_projected, 'analyzed_at', p_analyzed_at, 'superseded', false, 'current_version', v_current_projection); end; $function$
